"use client";

import { useMutation, useQueryClient } from "@tanstack/react-query";
import { AdminPropertiesService } from "@/features/properties/services/AdminPropertiesService";
import { PropertiesInput, propertiesSchema } from "@/validators/propertiesSchema";
import { toast } from "sonner";
import { useLanguage } from "@/contexts/LanguageContext";

const INTERNAL_ERROR_PATTERN = /Target class \[|SQLSTATE|Call to |Undefined |Stack trace|\.php\b/i;

/** True for framework/exception strings (e.g. "Target class [role] does not exist.") that must not reach the user. */
export function isServerInternalMessage(message: unknown): boolean {
  return typeof message === "string" && INTERNAL_ERROR_PATTERN.test(message);
}

function firstString(value: unknown): string | undefined {
  if (typeof value === "string") return value;
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = firstString(item);
      if (found) return found;
    }
  }
  return undefined;
}

function collectStrings(value: unknown): string[] {
  if (typeof value === "string") return [value];
  if (Array.isArray(value)) return value.flatMap(collectStrings);
  if (value && typeof value === "object") return Object.values(value).flatMap(collectStrings);
  return [];
}

/**
 * Normalizes a 422 `errors` payload into `{ field: firstMessage }`.
 * Handles both `{ field: ["msg"] }` and `[{ field: "msg" }]` shapes; returns null for anything else.
 */
export function getServerFieldErrors(error: unknown): Record<string, string> | null {
  const response = (error as { response?: { status?: number; data?: { errors?: unknown } } })?.response;
  if (response?.status !== 422) return null;
  const raw = response.data?.errors;
  if (!raw || typeof raw !== "object") return null;

  const entries = Array.isArray(raw)
    ? raw.flatMap((item) => (item && typeof item === "object" ? Object.entries(item) : []))
    : Object.entries(raw);

  const result: Record<string, string> = {};
  for (const [field, value] of entries) {
    const message = firstString(value);
    if (message && !(field in result)) result[field] = message;
  }
  return Object.keys(result).length > 0 ? result : null;
}

interface PropertyFormTab {
  fields: (keyof PropertiesInput)[];
}

interface ApplyServerFieldErrorsOptions<TTab extends PropertyFormTab> {
  tabs: TTab[];
  setError: (field: keyof PropertiesInput, error: { type: string; message: string }) => void;
  onShowTab: (tab: TTab) => void;
  getTabLabel: (tab: TTab) => string;
  t: (key: string, values?: Record<string, string | number>) => string;
}

/**
 * Maps a 422 response onto the property form: sets field errors, opens the tab of the first
 * invalid field and focuses it. Returns false when the error is not a field-validation error.
 */
export function applyServerFieldErrors<TTab extends PropertyFormTab>(
  error: unknown,
  { tabs, setError, onShowTab, getTabLabel, t }: ApplyServerFieldErrorsOptions<TTab>,
): boolean {
  const fieldErrors = getServerFieldErrors(error);
  if (!fieldErrors) return false;

  const formFields = Object.entries(fieldErrors).filter(
    ([field]) => field in propertiesSchema.shape,
  ) as [keyof PropertiesInput, string][];

  if (formFields.length === 0) {
    toast.error(Object.values(fieldErrors).join(", "));
    return true;
  }

  formFields.forEach(([field, message]) => setError(field, { type: "server", message }));

  const [firstField] = formFields[0];
  const targetTab = tabs.find((tab) => tab.fields.includes(firstField));
  if (targetTab) {
    onShowTab(targetTab);
    toast.error(t("properties.create.fillRequiredInTab", { tab: getTabLabel(targetTab) }));
  } else {
    toast.error(formFields.map(([, message]) => message).join(", "));
  }

  setTimeout(() => {
    const element =
      document.getElementById(firstField) || document.getElementsByName(firstField)[0];
    if (element) {
      element.focus();
      element.scrollIntoView({ behavior: "smooth", block: "center" });
    }
  }, 100);

  return true;
}

export default function useCreateProperty() {
  const queryClient = useQueryClient();
  const { t } = useLanguage();

  const mutation = useMutation({
    mutationFn: (data: PropertiesInput) => AdminPropertiesService.createProperty(data),
    onSuccess: async () => {
      toast.success(t("properties.messages.createSuccess"));
      await queryClient.invalidateQueries({ queryKey: ["properties"] });
      queryClient.removeQueries({ queryKey: ["properties"] });
    },
    onError: (error: any) => {
      // Field validation errors are mapped onto the form by the page.
      if (getServerFieldErrors(error)) throw error;

      const status: number | undefined = error?.response?.status;
      const flatMessages = collectStrings(error?.response?.data?.errors).join(", ");
      const serverMessage: string = flatMessages || error?.response?.data?.message || "";

      if (!error?.response || (status !== undefined && status >= 500) || !serverMessage || isServerInternalMessage(serverMessage)) {
        console.error("Failed to create property:", serverMessage || error?.message, error);
        toast.error(t("properties.messages.createFailed"));
      } else {
        toast.error(serverMessage);
      }
      throw error;
    },
  });

  return {
    createProperty: mutation.mutateAsync,
    isCreating: mutation.isPending,
    error: mutation.error,
    reset: mutation.reset,
  };
}
